def advanced_date_calculator(start_date, intervals, operation, consider_weekdays=False, exclude_holidays=[], time_zone='UTC'):
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate start_date
    try:
        start_date = datetime.fromisoformat(start_date)
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SS.'}

    # Set timezone
    try:
        tz = pytz.timezone(time_zone)
        start_date = start_date.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time_zone specified.'}

    # Process intervals
    for interval in intervals:
        value = interval.get('value')
        unit = interval.get('unit')

        if unit == 'seconds':
            delta = timedelta(seconds=value)
        elif unit == 'minutes':
            delta = timedelta(minutes=value)
        elif unit == 'hours':
            delta = timedelta(hours=value)
        elif unit == 'days':
            delta = timedelta(days=value)
        elif unit == 'weeks':
            delta = timedelta(weeks=value)
        elif unit == 'months':
            delta = relativedelta(months=value)
        elif unit == 'years':
            delta = relativedelta(years=value)
        else:
            return {'error': 'Invalid unit specified in intervals.'}

        if operation == 'add':
            start_date += delta
        elif operation == 'subtract':
            start_date -= delta
        else:
            return {'error': 'Invalid operation specified.'}

    # Consider weekdays and exclude holidays if specified
    if consider_weekdays or exclude_holidays:
        while start_date.weekday() >= 5 or start_date.strftime('%Y-%m-%d') in exclude_holidays:
            if consider_weekdays and start_date.weekday() >= 5:
                start_date += timedelta(days=1)
            if start_date.strftime('%Y-%m-%d') in exclude_holidays:
                start_date += timedelta(days=1)

    return {'result': start_date.strftime('%Y-%m-%d')}

