def enhanced_day_of_week_calculator(date, calendar_system='gregorian', output_format='text', timezone='UTC', historical_context=False):
    import datetime
    import pytz
    from dateutil import parser

    # Error handling for date format
    try:
        parsed_date = parser.parse(date)
    except ValueError:
        return {'error': 'Invalid date format. Please use YYYY-MM-DD.'}

    # Validate calendar system
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Unsupported calendar system. Choose from gregorian, julian, hebrew, islamic.'}

    # Validate timezone
    try:
        timezone_obj = pytz.timezone(timezone)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid timezone. Please use a valid IANA timezone format.'}

    # Adjust date for timezone
    localized_date = timezone_obj.localize(parsed_date)

    # Calculate day of the week
    if calendar_system == 'gregorian':
        day_of_week = localized_date.weekday()  # Monday is 0 and Sunday is 6
    elif calendar_system == 'julian':
        # Simplified Julian calendar calculation
        day_of_week = (localized_date.toordinal() + 1) % 7
    elif calendar_system == 'hebrew':
        # Placeholder for Hebrew calendar calculation
        day_of_week = (localized_date.toordinal() + 2) % 7
    elif calendar_system == 'islamic':
        # Placeholder for Islamic calendar calculation
        day_of_week = (localized_date.toordinal() + 3) % 7

    # Determine output based on format
    days_text = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
    if output_format == 'text':
        result = days_text[day_of_week]
    elif output_format == 'number':
        result = day_of_week
    elif output_format == 'detailed':
        result = {
            'day_name': days_text[day_of_week],
            'day_number': day_of_week,
            'historical_context': 'Note: Historical context is not implemented.' if historical_context else None
        }
    else:
        return {'error': 'Invalid output format. Choose from text, number, detailed.'}

    return result

