def date_calculator(input_date, days_offset, calendar_system='gregorian', output_format='YYYY-MM-DD', input_format='YYYY-MM-DD', operation='subtract_days'):
    from datetime import datetime, timedelta
    import calendar

    # Error handling for input date format
    try:
        if input_format == 'YYYY-MM-DD':
            date_obj = datetime.strptime(input_date, '%Y-%m-%d')
        else:
            # Custom input format handling can be added here
            raise ValueError('Unsupported input format')
    except ValueError as e:
        return {'error': str(e)}

    # Error handling for calendar system
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Unsupported calendar system'}

    # Perform the date operation
    if operation == 'subtract_days':
        result_date = date_obj - timedelta(days=days_offset)
    elif operation == 'add_days':
        result_date = date_obj + timedelta(days=days_offset)
    elif operation == 'difference_in_days':
        # This operation would require a second date input, not applicable here
        return {'error': 'Operation not applicable'}
    else:
        return {'error': 'Unsupported operation'}

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = result_date.strftime('%Y-%m-%d')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = result_date.strftime('%d-%m-%Y')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = result_date.strftime('%m-%d-%Y')
    elif output_format == 'custom':
        # Custom output format handling can be added here
        return {'error': 'Unsupported output format'}
    else:
        return {'error': 'Unsupported output format'}

    return {'result': formatted_date}

