def extract_last_name(full_name, delimiter=' ', name_format='first_last', case_sensitive=False, trim_whitespace=True, international_support=False):
    """
    Extracts the last name from a full name string based on the specified parameters.

    :param full_name: The full name from which the last name is to be extracted.
    :param delimiter: The character or string used to separate parts of the name.
    :param name_format: The format of the name.
    :param case_sensitive: Indicates whether the extraction should be case-sensitive.
    :param trim_whitespace: Indicates whether to trim whitespace from the extracted last name.
    :param international_support: Enables support for international naming conventions.
    :return: The extracted last name or an error message.
    """
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name:
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Split the full name based on the delimiter
    parts = full_name.split(delimiter)

    # Determine the index of the last name based on the name format
    last_name_index = -1
    if name_format in ['first_last', 'first_middle_last', 'prefix_first_last', 'first_last_suffix', 'first_middle_last_suffix']:
        last_name_index = -1  # Last element
    elif name_format in ['last_first', 'last_first_middle']:
        last_name_index = 0  # First element
    else:
        return {'error': 'Invalid name format specified.'}

    # Extract the last name
    try:
        last_name = parts[last_name_index]
    except IndexError:
        return {'error': 'Name format does not match the provided full name.'}

    # Handle case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    # Trim whitespace if required
    if trim_whitespace:
        last_name = last_name.strip()

    # Return the extracted last name
    return {'last_name': last_name}

