def string_length_counter(input: str, ignore_characters: list = [], ignore_character_classes: list = [], ignore_position: list = [], case_sensitive: bool = True, output_format: str = 'integer') -> str:
    # Validate output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return 'Error: Invalid output format specified.'

    # Validate ignore_character_classes
    valid_classes = ['digits', 'letters', 'whitespace', 'punctuation']
    if any(cls not in valid_classes for cls in ignore_character_classes):
        return 'Error: Invalid character class specified.'

    # Validate ignore_position
    valid_positions = ['first', 'last', 'even', 'odd']
    if any(pos not in valid_positions for pos in ignore_position):
        return 'Error: Invalid position specified.'

    # Prepare the input string
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Initialize count
    count = 0
    detailed_count = {'letters': 0, 'digits': 0, 'whitespace': 0, 'punctuation': 0}

    # Define helper functions
    def is_ignored(char, index):
        if char in ignore_characters:
            return True
        if 'digits' in ignore_character_classes and char.isdigit():
            return True
        if 'letters' in ignore_character_classes and char.isalpha():
            return True
        if 'whitespace' in ignore_character_classes and char.isspace():
            return True
        if 'punctuation' in ignore_character_classes and not char.isalnum() and not char.isspace():
            return True
        if 'first' in ignore_position and index == 0:
            return True
        if 'last' in ignore_position and index == len(input) - 1:
            return True
        if 'even' in ignore_position and index % 2 == 0:
            return True
        if 'odd' in ignore_position and index % 2 != 0:
            return True
        return False

    # Count characters
    for index, char in enumerate(input):
        if not is_ignored(char, index):
            count += 1
            if output_format == 'detailed':
                if char.isalpha():
                    detailed_count['letters'] += 1
                elif char.isdigit():
                    detailed_count['digits'] += 1
                elif char.isspace():
                    detailed_count['whitespace'] += 1
                else:
                    detailed_count['punctuation'] += 1

    # Return result based on output_format
    if output_format == 'integer':
        return str(count)
    elif output_format == 'text':
        return f'The string contains {count} characters.'
    elif output_format == 'detailed':
        return str(detailed_count)

