def date_calculator(start_date: str, months_to_add: int, days_to_add: int = 0, hours_to_add: int = 0, minutes_to_add: int = 0, calendar_system: str = 'Gregorian', output_format: str = 'YYYY-MM-DD') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Error handling for unsupported calendar systems
    if calendar_system not in ['Gregorian', 'Julian', 'ISO8601']:
        return 'Error: Unsupported calendar system.'

    # Error handling for date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return 'Error: Invalid date format. Expected YYYY-MM-DDTHH:MM:SS.'

    # Calculate the new date
    new_date = start_date_obj + relativedelta(months=months_to_add) + timedelta(days=days_to_add, hours=hours_to_add, minutes=minutes_to_add)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return new_date.strftime('%Y-%m-%d')
    elif output_format == 'text':
        return new_date.strftime('%A, %B %d, %Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        return new_date.strftime('%Y-%m-%dT%H:%M:%S')
    else:
        return 'Error: Unsupported output format.'

