    # Validate required parameter
    if not isinstance(film_titles, list) or not all(isinstance(title, str) for title in film_titles):
        return {'error': 'Invalid input: film_titles must be a list of strings.'}

    # Simulate database query
    directors_info = {
        'Goodbye Girl': {'name': 'Herbert Ross', 'year': 1977, 'bio': 'Herbert Ross was an American film director, producer, choreographer, and actor.', 'awards': ['Golden Globe']}
    }

    results = []
    for title in film_titles:
        # Simulate case sensitivity and partial match logic
        if not case_sensitive:
            title = title.lower()
            directors_info = {k.lower(): v for k, v in directors_info.items()}

        director_info = None
        if partial_match:
            for film_title in directors_info:
                if title in film_title:
                    director_info = directors_info[film_title]
                    break
        else:
            director_info = directors_info.get(title)

        if director_info:
            if output_format == 'name_only':
                result = director_info['name']
            elif output_format == 'detailed':
                result = {'name': director_info['name'], 'year': director_info['year']}
            elif output_format == 'full_bio':
                result = {'name': director_info['name'], 'bio': director_info['bio']}
            if include_awards:
                result['awards'] = director_info.get('awards', [])
            results.append(result)
        else:
            results.append({'error': f'Director not found for film: {title}'})

    return results

