    if trim_spaces:
        input = input.strip()

    # Error handling for empty string after trimming
    if not input:
        return 'Error: Input must be a non-empty string after trimming.'

    # Determine the first character based on allow_non_alphabetic
    first_char = None
    if allow_non_alphabetic:
        first_char = input[0]
    else:
        for char in input:
            if char.isalpha():
                first_char = char
                break
        if first_char is None:
            return 'Error: No alphabetic character found in input.'

    # Apply case sensitivity
    if not case_sensitive:
        first_char = first_char.lower()

    # Handle output format
    if output_format == 'text':
        return f'The first letter is: {first_char}'
    else:
