    if output_format not in ['string', 'array', 'detailed']:
        return {'error': "Invalid output_format. Must be one of ['string', 'array', 'detailed']."}

    # Splitting the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Logic to extract the last name based on the name format
    if name_format == 'western':
        # Assuming the last part is the last name
        last_name = name_parts[-1]
    elif name_format == 'eastern':
        # Assuming the first part is the last name
        last_name = name_parts[0]
    else:  # custom
