def extract_first_name(full_name: str, ignore_prefixes: bool = True, ignore_suffixes: bool = True, case_sensitive: bool = False, handle_middle_names: bool = False, compound_first_names: bool = True, cultural_naming_conventions: str = 'Western') -> str:
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return 'Error: full_name must be a non-empty string.'

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle prefixes and suffixes if needed
    if ignore_prefixes:
        prefixes = {'Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Miss'}
        name_parts = [part for part in name_parts if part not in prefixes]

    if ignore_suffixes:
        suffixes = {'Jr.', 'Sr.', 'III', 'IV'}
        name_parts = [part for part in name_parts if part not in suffixes]

    # Consider cultural naming conventions
    if cultural_naming_conventions == 'Western':
        # Western naming convention assumes first name is the first part
        first_name = name_parts[0] if name_parts else ''
    else:
        # Other cultural conventions can be added as needed
        first_name = name_parts[0] if name_parts else ''

    # Handle compound first names
    if compound_first_names and len(name_parts) > 1:
        # Check for common compound first name indicators
        if name_parts[1].lower() in {'anne', 'lee', 'jo'}:
            first_name = f"{first_name} {name_parts[1]}"

    # Handle case sensitivity
    if not case_sensitive:
        first_name = first_name.capitalize()

    return first_name

