def extract_last_name(full_name, delimiter=' ', case_sensitive=True, recognize_compound_names=False, suffix_handling=True, suffix_list=['Jr.', 'Sr.', 'II', 'III']):
    # Error handling for full_name
    if not isinstance(full_name, str) or not full_name.strip():
        return 'Error: full_name must be a non-empty string.'

    # Split the full name by the delimiter
    name_parts = full_name.split(delimiter)

    # Handle suffixes if suffix_handling is enabled
    if suffix_handling:
        name_parts = [part for part in name_parts if part not in suffix_list]

    # Handle compound last names if recognize_compound_names is enabled
    if recognize_compound_names:
        # Example logic for compound names
        compound_indicators = ['de', 'la', 'van', 'von']
        if len(name_parts) > 1 and name_parts[-2].lower() in compound_indicators:
            last_name = delimiter.join(name_parts[-2:])
        else:
            last_name = name_parts[-1]
    else:
        last_name = name_parts[-1]

    # Return the last name, considering case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    return last_name

