    # Define common prefixes and suffixes
    common_prefixes = ['Mr.', 'Ms.', 'Dr.', 'Prof.']
    common_suffixes = ['Jr.', 'Sr.', 'II', 'III']

    # Split the full name using the provided delimiters
    import re
    delimiter_pattern = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(delimiter_pattern, full_name)

    # Remove prefixes if required
    if ignore_prefixes:
        name_parts = [part for part in name_parts if part not in common_prefixes]

    # Remove suffixes if required
    if ignore_suffixes:
