def last_letter_extractor_v2(input: str, ignore_special_characters: bool = False, output_format: str = 'character', case_sensitive: bool = True, ignore_numbers: bool = False):
    # Error handling for invalid output_format
    if output_format not in ['character', 'ascii', 'unicode', 'hex']:
        return {'error': 'Invalid output_format. Must be one of: character, ascii, unicode, hex.'}

    # Error handling for non-string input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Process the input string based on the parameters
    if ignore_special_characters:
        input = ''.join(filter(str.isalnum, input))
    if ignore_numbers:
        input = ''.join(filter(lambda x: not x.isdigit(), input))
    if not input:
        return {'error': 'No valid characters to process.'}

    # Extract the last character
    last_char = input[-1]
    if not case_sensitive:
        last_char = last_char.lower()

    # Format the output based on output_format
    if output_format == 'ascii':
        return ord(last_char)
    elif output_format == 'unicode':
        return f'U+{ord(last_char):04X}'
    elif output_format == 'hex':
        return hex(ord(last_char))
    else:  # 'character'
        return last_char

