def extract_first_name(full_name: str, ignore_prefixes: bool = True, ignore_suffixes: bool = True, case_sensitive: bool = False, handle_middle_names: bool = False, initials_handling: str = 'ignore', cultural_naming_conventions: str = 'western', output_format: str = 'string', error_handling: str = 'strict') -> str:
    # Define common prefixes and suffixes
    prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.']
    suffixes = ['Jr.', 'Sr.', 'II', 'III']

    try:
        # Split the full name into parts
        name_parts = full_name.split()

        # Handle prefixes
        if ignore_prefixes:
            name_parts = [part for part in name_parts if part not in prefixes]

        # Handle suffixes
        if ignore_suffixes:
            name_parts = [part for part in name_parts if part not in suffixes]

        # Handle case sensitivity
        if not case_sensitive:
            name_parts = [part.lower() for part in name_parts]

        # Handle cultural naming conventions
        if cultural_naming_conventions == 'eastern':
            # In eastern naming conventions, the last name might come first
            first_name = name_parts[-1]
        else:
            first_name = name_parts[0]

        # Handle middle names
        if handle_middle_names and len(name_parts) > 2:
            first_name = name_parts[1]

        # Handle initials
        if initials_handling == 'ignore':
            first_name = ''.join([char for char in first_name if char.isalpha()])
        elif initials_handling == 'separate':
            first_name = ' '.join([char for char in first_name if char.isalpha()])

        # Format the output
        if output_format == 'json':
            return {'first_name': first_name}
        return first_name
    except Exception as e:
        if error_handling == 'strict':
            raise ValueError(f"Error extracting first name: {str(e)}")
        else:
            return ''

def longest_alphabetical_substring(input: str, case_sensitive: bool = False, output_format: str = 'substring', ignore_non_alpha: bool = True, max_results: int = 1):
    # Validate parameters
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if output_format not in ['substring', 'length', 'detailed']:
        return {'error': "output_format must be one of ['substring', 'length', 'detailed']."}
    if not isinstance(ignore_non_alpha, bool):
        return {'error': 'ignore_non_alpha must be a boolean.'}
    if not isinstance(max_results, int) or max_results < 1:
        return {'error': 'max_results must be an integer greater than or equal to 1.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Initialize variables
    longest_substring = ''
    current_substring = ''

    # Iterate over the input string
    for i in range(len(input)):
        if ignore_non_alpha and not input[i].isalpha():
            continue
        if i == 0 or input[i] >= input[i - 1]:
            current_substring += input[i]
        else:
            if len(current_substring) > len(longest_substring):
                longest_substring = current_substring
            current_substring = input[i]
    if len(current_substring) > len(longest_substring):
        longest_substring = current_substring

    # Prepare the output based on the specified format
    if output_format == 'substring':
        return longest_substring
    elif output_format == 'length':
        return len(longest_substring)
    elif output_format == 'detailed':
        return {'substring': longest_substring, 'length': len(longest_substring)}

    return longest_substring

