def extract_first_name(names, include_prefixes=False, include_suffixes=False, cultural_format='western', output_format='string'):
    # Error handling for required 'names' parameter
    if not isinstance(names, list) or len(names) == 0:
        return {'error': 'The names parameter must be a non-empty list of strings.'}

    # Initialize result list
    results = []

    # Iterate over each full name
    for full_name in names:
        # Split the name into parts
        name_parts = full_name.split()

        # Handle cultural format
        if cultural_format == 'eastern':
            first_name = name_parts[-1]  # Eastern convention often places the family name first
        else:
            first_name = name_parts[0]  # Default to western convention

        # Include prefixes if specified
        if include_prefixes and len(name_parts) > 1:
            first_name = name_parts[0] + ' ' + first_name

        # Include suffixes if specified
        if include_suffixes and len(name_parts) > 1:
            first_name += ' ' + name_parts[-1]

        # Prepare output based on specified format
        if output_format == 'array':
            results.append([first_name])
        elif output_format == 'detailed':
            results.append({'first_name': first_name, 'original_name': full_name, 'cultural_format': cultural_format})
        else:
            results.append(first_name)

    # Return results
    return results

